<?php header('Content-Type: application/json; charset=utf-8');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'error'=>'POST required']);exit;}$x=json_decode(file_get_contents('php://input'),true);if(!$x){http_response_code(400);echo json_encode(['ok'=>false,'error'=>'Invalid JSON']);exit;}$d=__DIR__.'/data';if(!is_dir($d))mkdir($d,0775,true);$f=$d.'/sent.json';$a=file_exists($f)?json_decode(file_get_contents($f),true):[];if(!is_array($a))$a=[];$a[]=$x;file_put_contents($f,json_encode($a,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);echo json_encode(['ok'=>true]);?>